import React, { useState } from 'react';
import { 
  Trash2, Plus, Users, MapPin, Play, Clock, 
  ShieldCheck, Globe, Layers, RefreshCw, 
  AlertTriangle, Calendar, CheckCircle, Info 
} from 'lucide-react';

const DepartmentCard = ({ deptName, deptCode, deptId, onGenerate, globalSchedule = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");

  // --- ENTITIES STATE ---
  const [subjects, setSubjects] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [] });
  const [proctors, setProctors] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [reactivatedProctors, setReactivatedProctors] = useState([]);

  // --- GENERATOR CONFIG ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- TEMPORARY INPUT STATES ---
  const [pName, setPName] = useState("");
  const [roomNum, setRoomNum] = useState("");
  const [avail, setAvail] = useState({ startD: '', endD: '', startT: '08:00', endT: '17:00' });

  // --- HANDLERS ---
  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const addProctor = () => {
    if (!pName) return;
    setProctors([...proctors, { id: Date.now(), name: pName.toUpperCase(), windows: [] }]);
    setPName("");
  };

  const addRoom = (type) => {
    if (!roomNum) return;
    setRooms([...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type }]);
    setRoomNum("");
  };

  const toggleReactivate = (name) => {
    setReactivatedProctors(prev => 
      prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name]
    );
  };

  // --- THE BRAIN: CONSECUTIVE & FALLBACK ALGORITHM ---
  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert(`Add subjects to Year ${selectedYear} first!`);
    if (rooms.length === 0) return alert("No rooms registered!");
    if (!examDates[0]) return alert("Please select an exam date!");

    // 1. Filter Vacant Rooms for the selected time slot
    const vacantRooms = rooms.filter(r => {
      const isOccupied = globalSchedule.some(as => 
        as.room === r.number && 
        as.exam_date === examDates[0] &&
        (startTime < as.end_time && endTime > as.start_time)
      );
      return !isOccupied;
    }).sort((a, b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

    if (vacantRooms.length < sectionCount) {
      return alert(`Insufficient rooms! Need ${sectionCount}, but only ${vacantRooms.length} vacant.`);
    }

    // 2. Consecutive Logic Attempt
    let assignedRoomNumbers = [];
    let isConsecutive = false;

    for (let i = 0; i <= vacantRooms.length - sectionCount; i++) {
      const slice = vacantRooms.slice(i, i + sectionCount);
      const consecutiveCheck = slice.every((room, idx) => {
        if (idx === 0) return true;
        // Check if current room number is exactly +1 of previous
        return parseInt(room.number) === parseInt(slice[idx - 1].number) + 1;
      });

      if (consecutiveCheck) {
        assignedRoomNumbers = slice.map(r => r.number);
        isConsecutive = true;
        break;
      }
    }

    // 3. Fallback to Scattered Rooms if Consecutive fails
    if (!isConsecutive) {
      assignedRoomNumbers = vacantRooms.slice(0, sectionCount).map(r => r.number);
    }

    // 4. Map to Output Data
    const generatedData = [];
    for (let s = 0; s < sectionCount; s++) {
      const sectionName = `Section ${String.fromCharCode(65 + s)}`;
      const roomForThisSection = assignedRoomNumbers[s];

      yearSubjects.forEach((sub) => {
        generatedData.push({
          subject_code: sub.code,
          subject_name: sub.name,
          section: sectionName,
          year_level: selectedYear,
          dept_code: deptCode,
          exam_date: examDates[0],
          start_time: startTime,
          end_time: endTime,
          room: roomForThisSection,
          room_badge: rooms.find(r => r.number === roomForThisSection)?.type || "Global",
          proctor: proctors[0]?.name || "STAFF",
          isConsecutive: isConsecutive
        });
      });
    }

    onGenerate(generatedData, examDates);
  };

  return (
    <div className="mb-12 bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden font-sans transition-all">
      {/* HEADER SECTION */}
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center border-b-4 border-blue-600">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="bg-blue-600 p-2 rounded-xl"><Layers size={20} /></div>
            <h2 className="text-4xl font-black uppercase tracking-tighter">{deptName}</h2>
          </div>
          <div className="flex items-center gap-2">
             <span className="text-blue-400 font-black text-[10px] tracking-[0.4em] uppercase">{deptCode}</span>
             <div className="h-1 w-1 bg-slate-700 rounded-full"></div>
             <span className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">Resource Registry v2.0</span>
          </div>
        </div>
        <div className="hidden md:flex gap-4">
            <div className="bg-slate-800/50 px-6 py-4 rounded-3xl border border-slate-700/50 backdrop-blur-sm text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase mb-1 tracking-widest">Local Proctors</p>
                <p className="text-2xl font-black text-white leading-none">{proctors.length}</p>
            </div>
            <div className="bg-slate-800/50 px-6 py-4 rounded-3xl border border-slate-700/50 backdrop-blur-sm text-center">
                <p className="text-[8px] font-black text-slate-500 uppercase mb-1 tracking-widest">Local Rooms</p>
                <p className="text-2xl font-black text-white leading-none">{rooms.length}</p>
            </div>
        </div>
      </div>

      {/* TAB NAVIGATION */}
      <div className="flex bg-slate-50 p-4 gap-4 border-b border-slate-200">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button 
            key={t} 
            onClick={() => setActiveTab(t)} 
            className={`flex-1 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all active:scale-95 ${activeTab === t ? 'bg-white shadow-xl text-blue-600 border border-slate-200 scale-[1.02]' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="p-10 min-h-[550px] bg-white">

        {/* 1. SUBJECTS TAB */}
        {activeTab === 'subjects' && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="grid grid-cols-5 gap-4 bg-blue-50 p-8 rounded-[2rem] border border-blue-100 shadow-inner">
                <div className="flex flex-col gap-2">
                    <label className="text-[9px] font-black text-blue-400 uppercase ml-1">Year Level</label>
                    <select className="bg-white p-4 rounded-2xl font-black text-xs shadow-sm border-none outline-none focus:ring-2 ring-blue-200" onChange={(e) => setSelectedYear(e.target.value)}>
                        {[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}
                    </select>
                </div>
                <div className="flex flex-col gap-2">
                    <label className="text-[9px] font-black text-blue-400 uppercase ml-1">Code</label>
                    <input placeholder="IT101" id="sC" className="p-4 rounded-2xl shadow-sm text-xs font-bold border-none uppercase focus:ring-2 ring-blue-200" />
                </div>
                <div className="flex flex-col gap-2 col-span-2">
                    <label className="text-[9px] font-black text-blue-400 uppercase ml-1">Subject Name</label>
                    <input placeholder="DATA STRUCTURES" id="sN" className="p-4 rounded-2xl shadow-sm text-xs font-bold border-none focus:ring-2 ring-blue-200" />
                </div>
                <div className="flex items-end">
                    <button onClick={() => {
                        const c = document.getElementById('sC').value; const n = document.getElementById('sN').value;
                        if(c && n) {
                          setSubjects({...subjects, [selectedYear]: [...subjects[selectedYear], {code: c, name: n}]});
                          document.getElementById('sC').value = ''; document.getElementById('sN').value = '';
                        }
                    }} className="w-full h-[52px] bg-blue-600 text-white rounded-2xl shadow-lg hover:bg-blue-700 flex justify-center items-center transition-all"><Plus /></button>
                </div>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {subjects[selectedYear].length > 0 ? subjects[selectedYear].map((s, i) => (
                    <div key={i} className="bg-white border-2 border-slate-50 p-5 rounded-3xl shadow-sm flex justify-between items-center group hover:border-blue-100 transition-all">
                        <div className="flex items-center gap-4">
                            <div className="bg-slate-100 p-2 rounded-lg text-[10px] font-black text-slate-400">{i+1}</div>
                            <span className="font-black text-xs text-slate-800 tracking-tight">{s.code}: <span className="text-slate-500 font-bold ml-1">{s.name}</span></span>
                        </div>
                        <button onClick={() => setSubjects({...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)})} className="text-slate-200 hover:text-red-500 transition-colors p-2"><Trash2 size={16} /></button>
                    </div>
                )) : (
                    <div className="col-span-2 text-center py-20 border-2 border-dashed border-slate-100 rounded-[2rem]">
                        <p className="text-slate-300 font-black text-[10px] uppercase tracking-widest">No subjects added for Year {selectedYear}</p>
                    </div>
                )}
             </div>
          </div>
        )}

        {/* 2. PROCTORS TAB */}
        {activeTab === 'proctors' && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="flex gap-4 p-8 bg-emerald-50 rounded-[2.5rem] border border-emerald-100 shadow-inner">
                <div className="flex-1">
                    <label className="text-[9px] font-black text-emerald-600 uppercase ml-1 block mb-2">Full Instructor Name</label>
                    <input value={pName} onChange={(e) => setPName(e.target.value)} placeholder="E.G. DR. JANE SMITH" className="w-full p-4 rounded-2xl shadow-sm text-xs font-black border-none focus:ring-2 ring-emerald-200" />
                </div>
                <div className="flex items-end">
                    <button onClick={addProctor} className="h-[52px] bg-emerald-600 text-white px-10 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-emerald-700 transition-all">Register</button>
                </div>
            </div>

            <div className="grid grid-cols-1 gap-6">
                {proctors.map(p => {
                    const globalAssigned = globalSchedule.find(as => as.proctor === p.name);
                    const isReactivated = reactivatedProctors.includes(p.name);

                    return (
                        <div key={p.id} className={`p-8 border-2 rounded-[3rem] transition-all ${globalAssigned && !isReactivated ? 'bg-amber-50/50 border-amber-100' : 'bg-white border-slate-50 shadow-sm'}`}>
                            <div className="flex justify-between items-start mb-6">
                                <div className="flex items-center gap-4">
                                    <div className={`p-3 rounded-2xl ${globalAssigned && !isReactivated ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-400'}`}><Users size={24} /></div>
                                    <div>
                                        <h4 className="text-xl font-black text-slate-800 uppercase tracking-tighter leading-none">{p.name}</h4>
                                        {globalAssigned && (
                                            <div className="flex items-center gap-2 mt-2">
                                                <span className="bg-amber-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">Currently Busy</span>
                                                <span className="text-[10px] font-bold text-amber-600 italic">Occupied by {globalAssigned.dept_code} (Room {globalAssigned.room})</span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    {globalAssigned && (
                                        <button 
                                          onClick={() => toggleReactivate(p.name)}
                                          className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase border transition-all ${isReactivated ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-amber-600 border-amber-200'}`}
                                        >
                                            {isReactivated ? "Reactivated" : "Unlock User"}
                                        </button>
                                    )}
                                    <button className="p-3 text-slate-200 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                                </div>
                            </div>

                            {/* Proctor Availability Grid */}
                            <div className="bg-slate-50/50 rounded-3xl p-6 border border-slate-100">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><Clock size={12}/> Time Availability Settings</p>
                                <div className="grid grid-cols-4 gap-4">
                                    <input type="date" className="p-3 rounded-xl text-[10px] font-bold border-none shadow-sm" />
                                    <input type="date" className="p-3 rounded-xl text-[10px] font-bold border-none shadow-sm" />
                                    <input type="time" className="p-3 rounded-xl text-[10px] font-bold border-none shadow-sm" />
                                    <button className="bg-slate-900 text-white rounded-xl flex items-center justify-center hover:scale-105 transition-all"><Plus size={16}/></button>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
          </div>
        )}

        {/* 3. ROOMS TAB */}
        {activeTab === 'rooms' && (
          <div className="space-y-8 animate-in slide-in-from-left-4 duration-500">
             <div className="flex gap-4 p-8 bg-amber-50 rounded-[2.5rem] border border-amber-100 shadow-inner items-center">
                <div className="flex-1">
                    <label className="text-[9px] font-black text-amber-600 uppercase ml-1 block mb-2">Room Identifier</label>
                    <input value={roomNum} onChange={(e)=>setRoomNum(e.target.value)} placeholder="E.G. 305" className="w-full p-4 rounded-2xl shadow-sm text-sm font-black border-none uppercase focus:ring-2 ring-amber-200" />
                </div>
                <div className="flex gap-3 items-end h-[52px] mt-6">
                    <button onClick={()=>addRoom('Department')} className="bg-amber-600 text-white px-6 h-full rounded-2xl font-black text-[10px] uppercase shadow-lg">Dept Only</button>
                    <button onClick={()=>addRoom('Global')} className="bg-slate-800 text-white px-6 h-full rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 shadow-lg"><Globe size={14}/> Add Global</button>
                </div>
             </div>

             <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                {rooms.map(r => {
                    const occupied = globalSchedule.find(as => as.room === r.number);
                    return (
                        <div key={r.id} className={`p-8 rounded-[2.5rem] border-2 flex flex-col items-center transition-all relative ${occupied ? 'border-rose-100 bg-rose-50/20' : 'border-slate-50 bg-white shadow-sm hover:border-amber-200'}`}>
                            <span className={`text-4xl font-black tracking-tighter leading-none ${occupied ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{r.number}</span>
                            <span className={`text-[8px] font-black px-3 py-1 rounded-full mt-3 uppercase ${r.type === 'Department' ? 'bg-blue-100 text-blue-600' : 'bg-slate-200 text-slate-500'}`}>{r.type}</span>
                            {occupied && (
                                <div className="mt-4 flex flex-col items-center">
                                    <span className="text-[8px] font-black text-rose-300 uppercase tracking-widest">Occupied by</span>
                                    <span className="text-[10px] font-black text-rose-600 uppercase mt-1">{occupied.dept_code}</span>
                                </div>
                            )}
                        </div>
                    );
                })}
             </div>
          </div>
        )}

        {/* 4. GENERATE TAB */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3.5rem] p-12 text-white relative shadow-2xl animate-in zoom-in-95 duration-500 overflow-hidden">
            {/* Visual Decoration */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 blur-[100px] rounded-full"></div>
            <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-600/10 blur-[100px] rounded-full"></div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-20 relative z-10">
              <div className="space-y-10">
                <div>
                  <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-[0.4em] mb-8 flex items-center gap-2 italic underline decoration-blue-500/50 decoration-4">Temporal Constraints</h4>
                  <div className="space-y-6">
                    <div className="flex justify-between items-center bg-slate-800/40 p-5 rounded-3xl border border-white/5">
                        <span className="text-xs font-black text-slate-400 uppercase tracking-tighter">Number of Days</span>
                        <input type="number" value={examDays} onChange={(e) => handleExamDayChange(e.target.value)} className="bg-slate-950 w-20 text-center py-3 rounded-xl font-black text-blue-400 text-lg border border-slate-800" />
                    </div>
                    <div className="space-y-3 max-h-[180px] overflow-y-auto custom-scrollbar pr-2">
                        {examDates.map((d, i) => (
                           <div key={i} className="flex items-center gap-4 bg-slate-800/20 p-4 rounded-2xl border border-white/5 hover:border-blue-500/30 transition-all">
                               <div className="bg-blue-600/20 text-blue-400 w-8 h-8 rounded-lg flex items-center justify-center font-black text-[10px]">{i+1}</div>
                               <input type="date" value={d} onChange={(e) => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="bg-transparent flex-1 outline-none text-sm font-black text-blue-100 uppercase" />
                           </div>
                        ))}
                    </div>
                    <div className="grid grid-cols-2 gap-4 pt-4">
                        <div className="bg-slate-800/30 p-5 rounded-3xl border border-white/5">
                            <label className="text-[9px] font-black text-slate-500 uppercase block mb-3">Starting Hour</label>
                            <input type="time" value={startTime} onChange={(e)=>setStartTime(e.target.value)} className="w-full bg-transparent text-xl font-black text-blue-400 outline-none" />
                        </div>
                        <div className="bg-slate-800/30 p-5 rounded-3xl border border-white/5">
                            <label className="text-[9px] font-black text-slate-500 uppercase block mb-3">Ending Hour</label>
                            <input type="time" value={endTime} onChange={(e)=>setEndTime(e.target.value)} className="w-full bg-transparent text-xl font-black text-blue-400 outline-none" />
                        </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-10">
                <div>
                  <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-[0.4em] mb-8 flex items-center gap-2 italic underline decoration-emerald-500/50 decoration-4">Allocation Engine</h4>
                  <div className="space-y-8">
                    <div className="flex justify-between items-center bg-slate-800/40 p-6 rounded-3xl border border-white/5">
                        <span className="text-xs font-black text-slate-300 uppercase tracking-tighter">Year Level</span>
                        <select value={selectedYear} onChange={(e)=>setSelectedYear(e.target.value)} className="bg-slate-950 border border-slate-800 p-3 rounded-xl font-black text-blue-400 text-xs w-40 outline-none">{[1,2,3,4,5].map(y=><option key={y} value={y}>Year Level {y}</option>)}</select>
                    </div>
                    <div className="flex justify-between items-center bg-slate-800/40 p-6 rounded-3xl border border-white/5">
                        <div className="flex items-center gap-3">
                            <span className="text-xs font-black text-slate-300 uppercase tracking-tighter">Number of Sections</span>
                            <div className="group relative text-slate-500"><Info size={14}/><div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 p-3 bg-slate-800 text-[9px] font-bold rounded-xl hidden group-hover:block border border-slate-700 shadow-2xl">This will attempt to find {sectionCount} consecutive rooms starting from the lowest vacant number.</div></div>
                        </div>
                        <input type="number" value={sectionCount} onChange={(e)=>setSectionCount(e.target.value)} className="bg-slate-950 w-20 text-center py-3 rounded-xl font-black text-emerald-400 text-lg border border-slate-800 outline-none" />
                    </div>

                    <div className="grid grid-cols-1 gap-4 pt-4">
                        <div className="flex justify-between items-center px-4"><span className="text-[10px] font-black text-slate-500 uppercase">Room Search Strategy</span><div className="flex bg-slate-950 p-1 rounded-2xl border border-slate-800"><button onClick={()=>setRoomSource("Department")} className={`px-6 py-3 text-[10px] font-black rounded-xl transition-all ${roomSource==='Department'?'bg-amber-600 text-white shadow-lg':'text-slate-500 hover:text-slate-300'}`}>DEPT PRIORITY</button><button onClick={()=>setRoomSource("Global")} className={`px-6 py-3 text-[10px] font-black rounded-xl transition-all ${roomSource==='Global'?'bg-blue-600 text-white shadow-lg':'text-slate-500 hover:text-slate-300'}`}>GLOBAL POOL</button></div></div>
                        <div className="flex justify-between items-center px-4"><span className="text-[10px] font-black text-slate-500 uppercase">Instructor Logic</span><div className="flex bg-slate-950 p-1 rounded-2xl border border-slate-800"><button onClick={()=>setProctorSource("Department")} className={`px-6 py-3 text-[10px] font-black rounded-xl transition-all ${proctorSource==='Department'?'bg-emerald-600 text-white shadow-lg':'text-slate-500 hover:text-slate-300'}`}>LOCAL ONLY</button><button onClick={()=>setProctorSource("Global")} className={`px-6 py-3 text-[10px] font-black rounded-xl transition-all ${proctorSource==='Global'?'bg-indigo-600 text-white shadow-lg':'text-slate-500 hover:text-slate-300'}`}>ALL SOURCES</button></div></div>
                    </div>
                  </div>
                </div>
                <button 
                  onClick={handleGenerateClick} 
                  className="group relative w-full bg-blue-600 hover:bg-blue-500 py-8 rounded-[2.5rem] font-black text-sm uppercase tracking-[0.4em] flex items-center justify-center gap-6 transition-all active:scale-95 shadow-[0_20px_50px_rgba(37,99,235,0.3)] overflow-hidden"
                >
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000"></div>
                    <Play size={24} fill="currentColor" /> Run Conflict-Free Engine
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
